def transform(grid):
    h, w = len(grid), len(grid[0])
    barrier_row = next(r for r, row in enumerate(grid) if all(v == 2 for v in row))
    step = -1 if barrier_row < h // 2 else 1

    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 2) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                cr, cc = stack.pop()
                cells.add((cr, cc))
                for nr, nc in ((cr - 1, cc), (cr + 1, cc), (cr, cc - 1), (cr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            objects.append((color, cells))

    if step < 0:
        objects.sort(key=lambda obj: min(r for r, c in obj[1]))
    else:
        objects.sort(key=lambda obj: max(r for r, c in obj[1]), reverse=True)

    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0}
    result = [row[:] for row in grid]

    for color, cells in objects:
        occupied.difference_update(cells)
        while True:
            moved = {(r + step, c) for r, c in cells}
            if any(r < 0 or r >= h or (r, c) in occupied for r, c in moved):
                break
            cells = moved
        for r, c in cells:
            result[r][c] = color
            occupied.add((r, c))

    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0, 2) and (r, c) not in occupied:
                result[r][c] = 0
    return result
